  'Creator Studio content management uses the same visibility model: public, unlisted, or private. Scheduled videos use requested visibility after release.' => 'Кіраванне кантэнтам Студыі стваральнікаў выкарыстоўвае тую ж мадэль бачнасці: агульнадаступную, недаступную або прыватную. Запланаваныя відэа выкарыстоўваюць запытаную бачнасць пасля выпуску.',
