  'Creators must provide accurate titles, descriptions, categories, languages, thumbnails, captions, visibility, and scheduling settings. Scheduled videos are not public until their scheduled time and successful processing.' => 'Стваральнікі павінны даць дакладныя назвы, апісанні, катэгорыі, мовы, мініяцюры, подпісы, бачнасць і налады раскладу. Запланаваныя відэа не з\'яўляюцца агульнадаступнымі да моманту іх запланаванага часу і паспяховай апрацоўкі.',
