  'Official contact addresses, billing contacts, and external support channels should be configured by the PlayHub site administrator for this deployment. This page intentionally does not display unverified email addresses.' => 'Афіцыйныя кантактныя адрасы, кантакты для выстаўлення рахункаў і знешнія каналы падтрымкі павінны быць настроены адміністратарам сайта PlayHub для гэтага разгортвання. На гэтай старонцы наўмысна не паказваюцца неправераныя адрасы электроннай пошты.',
  'On this page' => 'На гэтай старонцы',
  'Open Help Center' => 'Адкрыйце даведачны цэнтр',
  'Open settings' => 'Адкрыйце налады',
  'Open Settings, go to Security, then use the password or two-factor dialog. Two-factor delivery supports email or phone when configured.' => 'Адкрыйце «Настройкі», перайдзіце ў раздзел «Бяспека», затым выкарыстоўвайце пароль або двухфактарны дыялог. Двухфактарная дастаўка падтрымлівае электронную пошту або тэлефон, калі яна настроена.',
