  'Platform' => 'Платформа',
  'Playback' => 'Прайграванне',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'Прагрэс прайгравання, стан прагляду пазней, лайкі, каментарыі, падпіскі, апавяшчэнні і аналітыка адміністратара захоўваюцца ў базе даных пры прывязцы да функцый платформы з аўтэнтыфікацыяй.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'Прайграванне, каментарыі, лайкі, прагляд пазней, падпіскі, апавяшчэнні, паведамленні, спісы прайгравання і налады мовы даступныя праз галоўную навігацыю і меню ўліковага запісу.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub - гэта відэаплатформа для загрузкі, прагляду, планавання, кіравання і мадэрацыі кантэнту стваральніка з аднаго ўліковага запісу.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub - гэта відэаплатформа, якая працуе на гэтым разгортванні, створаная для стваральнікаў, гледачоў, суполак і аператараў платформы.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub забяспечвае каналы для стваральнікаў, запампоўку відэа, запланаваную публікацыю, падпіску, каментарыі, спісы прайгравання, прагляд пазней, старонкі жывога кантэнту і інструменты адміністравання з адной платформы.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub выкарыстоўвае асноўныя файлы cookie і сховішча браўзера для сеансаў уваходу ў сістэму, аўтэнтыфікацыі API, паводзін CSRF/бяспекі, выбару мовы, выбару тэмы, стану меню ўліковага запісу і іншых функцый, неабходных для працы прыкладання.',
  'playhub_language, theme' => 'playhub_language, тэма',
  'Popular questions' => 'Папулярныя пытанні',
  'Preference storage' => 'Пераважнае захоўванне',
  'Privacy Policy' => 'Палітыка прыватнасці',
