  'Refund' => 'Вяртанне грошай',
  'Refund and paid feature guidance.' => 'Рэкамендацыі па вяртанні грошай і аплаце.',
  'Refund handling for paid PlayHub features depends on billing records attached to this deployment.' => 'Апрацоўка вяртання грошай за платныя функцыі PlayHub залежыць ад рэальных рахункаў, далучаных да гэтага разгортвання.',
  'Refund handling is tied to billing records and administrator review. If billing is not configured for this deployment, there is no platform charge to refund.' => 'Апрацоўка вяртання прывязана да рэальных запісаў выстаўлення рахункаў і агляду адміністратара. Калі білінг не настроены для гэтага разгортвання, плата за платформу не спаганяецца.',
  'Refund issued' => 'Грошы вернуты',
  'Refund page' => 'Старонка вяртання грошай',
  'Refund Policy' => 'Палітыка вяртання сродкаў',
