  'Refund request' => 'Запыт на вяртанне грошай',
  'Refund request process' => 'Працэс запыту на вяртанне сродкаў',
  'refund-dialog contact-message-form' => 'вяртанне-дыялог кантактная-паведамленне-форма',
  'Registered users' => 'Зарэгістраваныя карыстальнікі',
  'Related legal pages' => 'Звязаныя юрыдычныя старонкі',
