  'Reports, moderation, and privacy.' => 'Справаздачы, мадэрацыя і прыватнасць.',
  'Reports, moderation, privacy, and community safety.' => 'Справаздачы, мадэрацыя, прыватнасць і бяспека супольнасці.',
  'Request a refund' => 'Запытаць вяртанне грошай',
  'Required' => 'абавязковы',
  'Required for login, security, and app routing.' => 'Патрабуецца для ўваходу ў сістэму, бяспекі і маршрутызацыі праграм.',
  'Response targets' => 'Мішэні рэагавання',
  'Retention and access' => 'Захаванне і доступ',
  'Review privacy and cookie details for this deployment.' => 'Праглядзіце дэталі прыватнасці і файлаў cookie для гэтага разгортвання.',
  'Rules for using this PlayHub deployment as a viewer, creator, or administrator.' => 'Правілы выкарыстання гэтага разгортвання PlayHub у якасці аглядальніка, стваральніка або адміністратара.',
  'Safety' => 'Бяспека',
  'Safety / technical' => 'Бяспека / тэхн',
  'Safety and content reports' => 'Справаздачы аб бяспецы і змесце',
  'Safety or report' => 'Бяспека або справаздача',
  'Sample endpoints' => 'Прыклад канчатковых кропак',
  'sample endpoints loaded' => 'узор канчатковых кропак загружаны',
  'Schedule video' => 'Відэа па графіку',
  'Scheduled video release and reminders.' => 'Запланаваны выпуск відэа і напаміны.',
  'Scheduled videos' => 'Запланаваныя відэа',
  'Scheduling a video release' => 'Планаванне выпуску відэа',
  'Search for answers...' => 'Шукаць адказы...',
  'Search help articles, topics, or questions...' => 'Шукайце даведкавыя артыкулы, тэмы ці пытанні...',
  'Select a reason' => 'Выберыце прычыну',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'Выберыце адзін ці некалькі відэафайлаў, увядзіце неабходныя звесткі, абярыце катэгорыю і мову, дадайце мініяцюру, абярыце бачнасць і апублікуйце. Вялікія файлы загружаюцца кавалкамі перад тым, як сервер пачне апрацоўку.',
  'Send a message and it will be saved for admins.' => 'Адпраўце паведамленне, і яно будзе захавана для адміністратараў.',
  'Send billing details to admin support for review.' => 'Адпраўце аплатную інфармацыю ў службу падтрымкі адміністратара для разгляду.',
  'Send message' => 'Адправіць паведамленне',
  'Send order details through the refund popup.' => 'Адпраўце дэталі замовы праз усплывальнае акно вяртання сродкаў.',
  'Send us a message' => 'Адпраўце нам паведамленне',
  'Sending...' => 'Адпраўка...',
  'Server configured' => 'Сервер наладжаны',
  'server records' => 'запісы сервера',
  'Service operation' => 'Аперацыя службы',
  'session, token' => 'сесія, маркер',
  'Settings and login' => 'Налады і ўваход',
  'Short summary' => 'Кароткі змест',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'Увайдзіце і выкарыстоўвайце налады для ўліковага запісу, профілю, пароля, апавяшчэнняў, прыватнасці і налад стваральніка. Праблемы з запампоўкай і змесцівам стваральніка павінны ўключаць назву відэа, канал, браўзер і любую памылку апрацоўкі, паказаную на старонцы запампоўкі.',
  'Sign in for account support' => 'Увайдзіце ў службу падтрымкі ўліковага запісу',
  'Signed in' => 'Выкананы ўваход',
  'Start uploading' => 'Пачніце загрузку',
  'Still can’t find an answer?' => 'Усё яшчэ не можаце знайсці адказ?',
  'Stored for admins' => 'Захоўваецца для адміністратараў',
  'Stores language, theme, and interface preferences.' => 'Захоўвае налады мовы, тэмы і інтэрфейсу.',
  'Studio, playlists, analytics, channels.' => 'Студыя, плэйлісты, аналітыка, каналы.',
  'Submit a billing or refund message to admin support.' => 'Адпраўце паведамленне аб выстаўленні рахунку або вяртанні сродкаў у службу падтрымкі адміністратара.',
  'Submit refund request' => 'Адпраўце запыт на вяртанне грошай',
  'Submit request' => 'Падаць запыт',
  'Subscription cancellation' => 'Адмена падпіскі',
  'Support dashboard' => 'Панэль падтрымкі',
  'System status' => 'Стан сістэмы',
  'Table' => 'стол',
  'Taxonomies' => 'Таксанаміі',
  'Technical issue' => 'Тэхнічнае пытанне',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'Тэхнічныя заўвагі па інтэграцыі з бягучым API PlayHub і працоўным працэсам загрузкі.',
  'Tell us more about your question or request...' => 'Раскажыце больш пра сваё пытанне або запыт...',
  'Terms of Use' => 'Умовы выкарыстання',
  'The configured' => 'Наладжаны',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'Старонка распрацоўшчыка падключана да аператыўнага бэкэнда Laravel: інвентар маршрутаў, колькасць баз дадзеных, ліміты загрузкі і метаданыя платформы загружаюцца з /api/developers.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'Інтэрфейс захоўвае налады, такія як выбраная мова, тэма, чарга прайгравання, ход прагляду і стан інтэрфейсу, таму вопыт застаецца аднолькавым пры навігацыі па старонках і пры перазагрузцы.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'Заданне апрацоўкі кадуе прайграванне, стварае мініяцюры, калі гэта неабходна, захоўвае субцітры і пазначае відэа як гатовае пасля завяршэння апрацоўкі. Будучыя запланаваныя відэа застаюцца прыватнымі, пакуль планавальнік не выпусціць іх.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'Сістэма загрузкі падтрымліваецца базай дадзеных, падтрымлівае катэгорыі і мовы з API, апрацоўвае загружаныя відэа, захоўвае мініяцюры і подпісы і захоўвае запланаваны кантэнт у прыватнасці да моманту яго выпуску.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'На гэтай старонцы тлумачыцца, як PlayHub выкарыстоўвае файлы cookie і сховішча браўзера для сеансаў, бяспекі, налад, прайгравання і функцый аўтэнтыфікацыі.',
  'Ticket source' => 'Крыніца білетаў',
  'Top content categories' => 'Лепшыя катэгорыі кантэнту',
  'Topic' => 'Тэма',
  'Transaction / invoice' => 'Здзелка / рахунак-фактура',
  'Transaction / invoice ID' => 'Ідэнтыфікатар транзакцыі / рахунку-фактуры',
  'Unable to send message.' => 'Немагчыма адправіць паведамленне.',
  'Unable to submit refund request.' => 'Немагчыма адправіць запыт на вяртанне грошай.',
  'Understanding admin support tickets' => 'Разуменне білетаў падтрымкі адміністратара',
  'Upload and processing help' => 'Даведка па загрузцы і апрацоўцы',
  'Upload chunks' => 'Загрузіць кавалкі',
  'Upload issues' => 'Праблемы з загрузкай',
  'Upload languages' => 'Загрузіць мовы',
  'Upload limit' => 'Ліміт загрузкі',
  'Upload options' => 'Параметры загрузкі',
  'Upload or processing' => 'Загрузка або апрацоўка',
  'Upload page' => 'Старонка загрузкі',
  'Upload pipeline' => 'Канвеер загрузкі',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'Запампоўвайце, глядзіце, падпісвайцеся, мадэруйце і стварайце з жывымі дадзенымі PlayHub.',
  'Uploaded videos' => 'Запампаваныя відэа',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'Запампаваныя відэа кадзіруюцца ў прайграваныя прайграванні. Час апрацоўкі залежыць ад памеру файла, працягласці, загрузкі сервера і стану чаргі. Старонка загрузкі і Creator Studio паказваюць рэальны стан апрацоўкі відэазапісу.',
  'Uploads, scheduling, and processing are available.' => 'Даступныя загрузка, планаванне і апрацоўка.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'Выкарыстоўвайце /api/videos, канчатковыя кропкі канала і аўтэнтыфікаваныя маршруты для працоўных працэсаў стваральнікаў.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'Выкарыстоўвайце ўбудаваныя дзеянні па справаздачах для відэа і каментарыяў, каб адміністратары атрымлівалі дакладную спасылку на кантэнт. На старонках прыборнай панэлі адміністратара выкарыстоўваюцца жывыя даныя базы дадзеных для карыстальнікаў, кантэнту, справаздач, манетызацыі, аналітыкі, падтрымкі, роляў і налад сістэмы.',
  'Use Contact Us' => 'Скарыстайцеся Звязацца з намі',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'Выкарыстоўвайце JSON для звычайных запытаў API і FormData для загрузкі файлаў. Не абыходзьце праверку: катэгорыі і мовы з\'яўляюцца ідэнтыфікатарамі баз дадзеных, бачнасць абмежавана агульнадаступнымі, недаступнымі або прыватнымі, а субцітры прымаюць файлы SRT, VTT або TXT.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'Выкарыстоўвайце Налады, каб абнавіць свой профіль, бяспеку, пароль, двухфакторную дастаўку, прылады, перавагі і параметры апавяшчэнняў. Калі вы не можаце атрымаць доступ да свайго ўліковага запісу, выкарыстоўвайце працэдуру ўваходу і падайце адрас электроннай пошты ўліковага запісу адміністратару сайта.',
  'Use the contact form' => 'Выкарыстоўвайце кантактную форму',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'Выкарыстоўвайце дзеянні па справаздачах для відэа, каментарыяў і паведамленняў у супольнасці, каб адміністратары атрымлівалі дакладную спасылку на кантэнт.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'Выкарыстоўвайце дзеянні па справаздачах да відэа, каментарыяў і паведамленняў у супольнасці, калі змесціва можа парушаць правілы платформы. Гэтыя справаздачы звязаны з запісам рэальнага змесціва і лепш, чым агульнае паведамленне, таму што адміністратары могуць праглядаць дакладны элемент.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'Выкарыстоўвайце правільны канал PlayHub для атрымання дапамогі па ўліковым запісе, справаздач аб змесціве, тэхнічных праблем і запытаў адміністратара.',
  'Video categories' => 'Катэгорыі відэа',
  'Video for everyone. Built for creators and viewers.' => 'Відэа для ўсіх. Створаны з дадзеных рэальнай платформы.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'Праблемы з загрузкай відэа, планаваннем, эскізамі і апрацоўкай.',
  'Videos, thumbnails, captions, processing.' => 'Відэа, мініяцюры, тытры, апрацоўка.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'Гледачы могуць праглядаць катэгорыі, шукаць відэа, глядзець змесціва, падпісвацца на каналы, захоўваць відэа для прагляду пазней, каментаваць, атрымліваць апавяшчэнні і кіраваць мовай і наладамі даступнасці.',
  'Viewing and community help' => 'Прагляд і дапамога супольнасці',
  'Waiting for backend endpoint inventory.' => 'Чаканне інвентарызацыі канчатковай кропкі бэкэнда.',
  'We’re here to help.' => 'Мы тут, каб дапамагчы.',
  'What is PlayHub?' => 'Што такое PlayHub?',
  'What PlayHub does' => 'Што робіць PlayHub',
  'Where do contact messages go?' => 'Куды ідуць кантактныя паведамленні?',
  'Why is my video still processing?' => 'Чаму маё відэа ўсё яшчэ апрацоўваецца?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'так. Выкарыстоўвайце роднае поле даты і часу раскладу на старонцы загрузкі. Бэкэнд захоўвае scheduled_at, апрацоўвае відэа, захоўвае яго прыватным, пакуль дата ў будучыні, і выпускае яго, калі планавальнік Laravel запускаецца пасля запланаванага часу.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'так. Выкарыстоўвайце роднае поле раскладу на Upload. Бэкэнд захоўвае scheduled_at і выпускае відэа пасля апрацоўкі, калі наступае запланаваны час.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'Вы праглядаеце як госць. Увайдзіце, каб атрымаць доступ да інструментаў для ўліковага запісу.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'Вы несяце адказнасць за ўліковыя даныя вашага ўліковага запісу, дзейнасць у профілі, запампаваны кантэнт, каментарыі, паведамленні і любыя дзеянні стваральніка або адміністратара, якія выконваюцца з вашага ўліковага запісу. Выкарыстоўвайце надзейныя паролі і падтрымлівайце актуальныя двухфактарныя метады дастаўкі.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'Вы можаце ачысціць файлы cookie браўзера і лакальнае сховішча ў наладах браўзера. Ачыстка важнага сховішча можа прывесці да выхаду з сістэмы, скіду параметраў мовы/тэмы, выдалення лакальнага стану прайгравання і неабходнасці паўторнага ўваходу.',
  'You receive a response by email.' => 'Вы атрымаеце адказ па электроннай пошце.',
  'You’re in control' => 'Вы пад кантролем',
  'Your choices' => 'Ваш выбар',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'Ваша паведамленне захоўваецца непасрэдна ў бэкэнд вэб-сайта і адлюстроўваецца на панэлі кіравання адміністратара ў раздзеле "Падтрымка".',
  'Your support' => 'Ваша падтрымка',
  'Watch video' => 'Глядзець відэа',
  'Copy link' => 'Скапіраваць спасылку',
  'View creator' => 'Прагляд стваральніка',
  'Remove from playlist' => 'Выдаліць з плэйліста',
  'Removing videos from playlists is not available here yet.' => 'Выдаленне відэа з плэйлістоў тут пакуль недаступна.',
  'Create New Playlist' => 'Стварыць новы спіс прайгравання',
  'Organize your videos into a playlist' => 'Арганізуйце свае відэа ў спіс прайгравання',
  'Playlist Name' => 'Назва плэйліста',
  'e.g. Travel Vlogs 2025' => 'напр. Відэаблогі падарожжаў 2025',
  '(optional)' => '(неабавязкова)',
  'What’s this playlist about?' => 'Пра што гэты плэйліст?',
  'Select Color' => 'Выберыце Колер',
  'This color will represent your playlist' => 'Гэты колер будзе прадстаўляць ваш спіс прайгравання',
  'Anyone can view this playlist' => 'Любы можа праглядаць гэты плэйліст',
  'Only you can view this playlist' => 'Толькі вы можаце праглядаць гэты плэйліст',
  'Anyone with the link can view' => 'Любы, хто мае спасылку, можа праглядаць',
  'Add to Playlist' => 'Дадаць у спіс прайгравання',
